function toastHTML(text,err){return (err?'<p class="notice toast error" role="alert">':'<p class="notice toast success">')+icon(err?'alert-circle':'check-circle')+'<span>'+esc(text)+'</span><button type="button" class="toast-close" data-toast-close aria-label="Close">'+icon('x',{size:16})+'</button></p>';}
window.addEventListener('hashchange',()=>{const q=new URLSearchParams(location.hash.slice(1));const big=(q.get('view')||'home')!==route.view||(q.get('p')||route.p)!==route.p;if(!big||!document.startViewTransition||matchMedia('(prefers-reduced-motion:reduce)').matches){loadRoute();return;}let done=false;const go=()=>{if(!done){done=true;loadRoute();}};const vt=document.startViewTransition(go);vt.ready.catch(()=>{});setTimeout(()=>{if(!done){vt.skipTransition();go();}},250);});
document.addEventListener('click',e=>{const x=e.target.closest('[data-toast-close]');if(x)x.closest('.notice')?.remove();});
// 登出（2026-11-01）：先在這台裝置清掉自己未送出的這一批，再回登入頁；寫入失敗也照樣登出。
document.addEventListener('click',e=>{if(!e.target.closest('.logout-link'))return;try{store.dispatch('logout',route.actor,{});}catch(err){}});function runMany(list,doneMessage){let last=null;try{list.forEach(([action,data])=>{last=store.dispatch(action,route.actor,{...data});});messageError=!!last&&!last.saved;message=last?(messageError||!doneMessage?last.message:doneMessage):'';}catch(e){message=e.message;messageError=true;}if(!messageError&&list.some(([action])=>action==='reviewNote')){route.preview='0';route.printType='';route.printId='';history.replaceState(null,'',url());}render();if(messageError)document.getElementById('message').scrollIntoView({block:'start'});}
